"""One source-compatible dashboard, compact enough for private hosted delivery."""
import argparse,base64,gzip
from pathlib import Path
import engine,collection_watch,integrated_transport

def export(runtime,output,run_id=None):
 runtime=Path(runtime).resolve();output=Path(output).resolve()
 if output.is_relative_to(runtime) or not (runtime/'audit.sqlite').is_file():raise ValueError('Existing projection custody and external output required')
 with engine.Engine(runtime) as e:
  e.db.execute('BEGIN')
  try:
   head=e.verify();run=e.db.execute("SELECT * FROM runs WHERE json_extract(rules_json,'$.kind')='integrated_reconstruction' AND (? IS NULL OR id=?) ORDER BY at DESC,id DESC LIMIT 1",(run_id,run_id)).fetchone()
   if not run:raise ValueError('Integrated execution missing')
   original=engine.load_json_bytes(collection_watch.object_bytes(e,run['snapshot_hash']));packed,transport=integrated_transport.pack(original)
   if integrated_transport.restore(packed,transport)!=original:raise ValueError('Projection transport lost source references')
   data={'run_id':run['id'],'snapshot_sha256':run['snapshot_hash'],'ledger_head':head,'result':packed,'transport':transport}
  finally:e.db.execute('ROLLBACK')
 payload=base64.b64encode(gzip.compress(engine.canonical(data).encode(),mtime=0)).decode()
